// Involute helical gears, cut the way they are made.
//
// **An external gear is generated by a helical rack**, as a hob or a rack-type shaper cuts one.
// The rack's tooth is drawn in the *normal* section — square to the tooth's length — as a
// straight-sided trapezoid at the normal pressure angle, and that plane is leaned `beta` across
// the gear's face, so the tooth crosses the blank aslant.  The blank turns while the rack slides
// along its pitch line a pitch circumference a turn: the line rolls on the pitch circle, and what
// the tooth passes through is one tooth space, its flanks involute helicoids and its root the
// trochoid the tooth's tip corners trace.  Nothing here writes an involute, a helix or a
// trochoid: they are what the motion leaves (`solid_sweeps/helical.sv` is one space of this).
//
// **An internal gear is shaped by an external gear of its own count and hand.**  An internal
// gear's tooth space is an external gear's tooth, so the ring is its annulus less the gear whose
// teeth are its spaces (`solid_sweeps/ring_gear.sv`), here a helical one: a gear shaper cutting a
// helical ring uses a helical cutter and a helical guide of the same lead.
//
// Every gear is drawn about its own origin, its axis its frame's `std.z`, its mid-plane its frame's
// `std.top`, and given only numbers: closed (#577), so the three planets of one binding are one
// solid evaluated once and placed three times.  At roll 0 a gear has a tooth *space* centred on its
// `std.x` in its mid-plane: the rack's tooth stands there.
unit mm
use std
use std.solids
use std.solids (cut, union)
use std.rounds (chamfer)
use std.place (horizontal, on_u, coords, right_of, above)
use std.motion (spins, slides)

// An external involute helical gear.
//
// - `N` teeth, normal module `mn`, normal pressure angle `alpha`, helix angle `beta` at the pitch
//   cylinder, `hand` +1 right-handed and -1 left-handed;
// - `width` the face width, about the mid-plane;
// - `ha` the addendum (the tip circle stands `ha` outside the pitch circle) and `hf` the dedendum
//   (the rack's tip reaches `hf` inside it): a stub tooth, `ha` < `hf`, keeps tip clearance in
//   mesh without a deeper cut than the rack can make without undercutting a small count;
// - `backlash` the normal backlash this gear takes up: its teeth are thinned by half of it, so a
//   pair of such gears runs with `backlash` between the flanks.  A negative backlash thickens the
//   teeth, as a shaper's are made to open its ring's spaces;
// - `bore` the bore's diameter (none at `0mm`), `edge` the chamfer the blank's rim is broken by at
//   both faces before the teeth are cut (none at `0mm`), so every tooth's tip ends in a chamfer;
// - a hub, `hub_r` its radius (none at `0mm`), from `hub_from` to `hub_to` along the axis: the
//   sun's sleeve.  It stands inside the root, so the teeth's cut never reaches it.
component Helical(N: Int, mn: Length, alpha: Angle, beta: Angle, hand: Scalar, width: Length,
                  ha: Length, hf: Length, backlash: Length, bore: Length, edge: Length,
                  hub_r: Length, hub_from: Length, hub_to: Length) {
  // the transverse pitch radius: the normal pitch over the helix's lean
  rp := N * mn / (2 * cos(beta))
  // half the rack tooth's thickness at its pitch line: half the gear's space, normal section
  hw := pi * mn / 4 + backlash / 4

  in std.top {
    o := point
    o coincident std.top.origin
    rim := circle(center: o)
    radius(rp + ha) rim
    // the rack's pitch line, tangent to the pitch circle where its tooth cuts
    s0 := point
    s1 := point
    s0 right_of(d: rp) o
    s1 above(d: 10mm) s0
    construction pitch_line := line(s0, s1)
  }

  // The normal section: the plane through the radius to the pitch point, leaned `beta` from the
  // face about that radius.  Its `u` runs out along the radius, its `v` along the tooth's crossing.
  in std.side {
    l0 := point
    l1 := point
    l2 := point
    fix((0mm, 0mm)) l0
    construction across := line(l0, l2)
    construction lean := line(l0, l1)
    horizontal across
    length(10mm) across
    length(10mm) lean
    l0 distance(>= 0mm, along: u) l2
    across angle(-hand * beta) lean
  }
  normal := plane(u: std.x, v: lean)

  // The rack's tooth in the normal section: a trapezoid whose flanks lean `alpha` from the radius
  // and cross the pitch line `2 hw` apart; its tip `hf` inside the pitch line, its back past the
  // gear's tip.
  in normal {
    i1 := point
    i1 on_u(d: 10mm) normal
    construction radial := line(normal.origin, i1)
    pr := point
    pl := point
    pr coords(du: rp, dv: hw) normal
    pl coords(du: rp, dv: -hw) normal
    t0 := point
    t1 := point
    t2 := point
    t3 := point
    normal.origin distance(rp - hf, along: u) t0
    normal.origin distance(rp - hf, along: u) t1
    normal.origin distance(rp + 2 * mn, along: u) t2
    normal.origin distance(rp + 2 * mn, along: u) t3
    rack := (tip := line(t0, t1)) -> (right := line(t1, t2)) -> (back := line(t2, t3)) ->
            (left := line(t3, t0)) -> close
    pr coincident right
    pl coincident left
    radial angle(alpha) right
    radial angle(180deg - alpha) left
  }
  // the rack's tooth, longer than the blank is wide along its own slant
  construction tooth := solid(std.solids.Prism(rack, from: -width, to: width))

  // the blank: the tip cylinder, its rim broken at both faces, bored and hubbed
  blank := solid(std.solids.Prism(face(rim), from: -width / 2, to: width / 2))
  when edge > 0mm {
    blank.near chamfer(d: edge) blank.rim
    blank.far chamfer(d: edge) blank.rim
  }
  when hub_r > 0mm {
    in std.top {
      hub_c := circle(center: o)
      radius(hub_r) hub_c
    }
    hub := solid(std.solids.Prism(face(hub_c), from: hub_from, to: hub_to))
    hub union blank
  }
  when bore > 0mm {
    in std.top {
      bore_c := circle(center: o)
      radius(bore / 2) bore_c
    }
    construction bore_cut := solid(std.solids.Prism(face(bore_c),
      from: min(-width, hub_from) - 1mm, to: max(width, hub_to) + 1mm))
    bore_cut cut blank
  }

  // The blank turns about its axis, and the rack slides a pitch circumference a turn: the rack
  // rolls on the pitch circle.  The space is what the tooth passes through as the blank sees it,
  // over every roll it meets the blank; one space is cut a pitch apart at every tooth.
  turn := frame
  turn spins(1) o
  feed := frame
  feed slides(2 * pi * rp) pitch_line
  construction space := solid({ p | some t: p in tooth at(under: feed, seen_from: turn) t })
  body := solid(blank)
  repeat N as i {
    construction indexed := space at(under: turn) i * 360deg / N
    indexed cut body
  }
}

// An internal involute helical gear: the ring `od` across, `width` wide, its teeth's tips on the
// circle `ha` inside the pitch circle, its spaces `hf` deep outside it, cut by a helical shaper of
// its own count and hand whose teeth are its spaces.  `backlash` widens the spaces (the shaper's
// teeth are that much thicker), and `edge` breaks the bore's rim at both faces before the teeth
// are cut.
component Ring(N: Int, mn: Length, alpha: Angle, beta: Angle, hand: Scalar, width: Length,
               od: Length, ha: Length, hf: Length, backlash: Length, edge: Length) {
  rp := N * mn / (2 * cos(beta))
  shaper := Helical(N: N, mn: mn, alpha: alpha, beta: beta, hand: hand, width: width + 2mm,
    ha: hf, hf: ha + 0.5 * mn, backlash: -backlash, bore: 0mm, edge: 0mm, hub_r: 0mm,
    hub_from: 0mm, hub_to: 0mm)
  in std.top {
    outer := circle(center: std.top.origin)
    radius(od / 2) outer
    tips := circle(center: std.top.origin)
    radius(rp - ha) tips
  }
  annulus := solid(std.solids.Prism(face(outer, holes: tips), from: -width / 2, to: width / 2))
  when edge > 0mm {
    annulus.near chamfer(d: edge) annulus.tips
    annulus.far chamfer(d: edge) annulus.tips
  }
  body := solid(annulus)
  shaper.body cut body
}

preview {
  // a 15-tooth planet and the 60-tooth ring it runs in, at the drive's numbers
  planet := Helical(N: 15, mn: 1mm, alpha: 20deg, beta: 20deg, hand: -1, width: 14mm, ha: 0.8mm,
    hf: 1mm, backlash: 0.04mm, bore: 7mm, edge: 0.3mm, hub_r: 0mm, hub_from: 0mm, hub_to: 0mm)
}
